L(){ printf '%s  %-20s%s\n' "$1" "$2" "$3"; }; echo; b=$(command -v brew); if [ -n "$b" ]; then L ○ Homebrew "$b"; elif [ -x /opt/homebrew/bin/brew ] || [ -x /usr/local/bin/brew ]; then L △ Homebrew '入っているが見つからない（このあと直す）'; else L × Homebrew 'ない'; fi; c=$(xcode-select -p 2>/dev/null); if [ -n "$c" ]; then L ○ 'Command Line Tools' "$c"; L ○ git "$(command -v git)"; else L × 'Command Line Tools' 'ない（git はこの中に入っている）'; L × git 'ない'; fi; v=$(command -v code); if [ -n "$v" ]; then L ○ 'VS Code' "$v"; elif [ -d '/Applications/Visual Studio Code.app' ] || [ -d "$HOME/Applications/Visual Studio Code.app" ]; then L △ 'VS Code' '入っているが code コマンドがない（このあと直す）'; else L × 'VS Code' 'ない'; fi; d=$(command -v docker); if [ -d /Applications/Docker.app ]; then if [ -n "$d" ]; then L ○ Docker "$d"; else L △ Docker '入っているが docker コマンドがない（このあと直す）'; fi; elif [ -n "$d" ]; then L ※ Docker "Docker Desktop ではない docker：$d"; else L × Docker 'ない'; fi; h=$(command -v gh); if [ -n "$h" ]; then L ○ gh "$h"; else L × gh 'ない'; fi; n=$(command -v node); if [ -n "$n" ]; then L ・ Node.js "ある（この教材では使わない）：$n"; else L ・ Node.js 'ない（なくてよい）'; fi; echo; echo '○ 使える　△ あるが、まだ使えない　× まだない　※ メンターと確かめる　・ 参考'; echo
